mapper.select:
        select
        subscribe.*,
        student.stu_name,
        student.stu_img,
        seat.number,
        studyhall.name
        from subscribe subscribe
        left join student student on subscribe.stu_id = student.id
		left join seat seat on subscribe.seat_id = seat.id
		left join studyhall studyhall on subscribe.hall_id = studyhall.id

            and subscribe.id = #{id}
            and subscribe.stu_id = #{stuId}
            and subscribe.hall_id = #{hallId}
            and subscribe.seat_id = #{seatId}
            and subscribe.status = #{status}
            and subscribe.create_time = #{createTime}
            and student.stu_name like concat('%',#{stuName},'%')
            and student.stu_img = #{stuImg}
            and seat.number = #{number}
            and studyhall.name like concat('%',#{name},'%')


            limit #{current},#{pageSize}

        select count(*) from subscribe subscribe
        left join student student on subscribe.stu_id = student.id
		left join seat seat on subscribe.seat_id = seat.id
		left join studyhall studyhall on subscribe.hall_id = studyhall.id

            and subscribe.id = #{id}
            and subscribe.stu_id = #{stuId}
            and subscribe.hall_id = #{hallId}
            and subscribe.seat_id = #{seatId}
            and subscribe.status = #{status}
            and subscribe.create_time = #{createTime}
            and student.stu_name like concat('%',#{stuName},'%')
            and student.stu_img = #{stuImg}
            and seat.number = #{number}
            and studyhall.name like concat('%',#{name},'%')
